input.sparql:
SELECT ?s ?name ?tsid ?class WHERE {
  ?s rdfs:label ?name .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
  ?s ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid
}

SELECT ?s ?name WHERE {
  ?s rdfs:label ?name .
  FILTER(CONTAINS(?name, "hiller") || CONTAINS(?name, "ump") || CONTAINS(?name, "ondP"))
}

SELECT ?s ?tsid WHERE {
  ?s ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid
  FILTER(str(?s) CONTAINS "Chiller02_Electric_Power_Sensor" || str(?s) CONTAINS "CondPump01_Electric_Power_Sensor" || str(?s) CONTAINS "CondPump02_Electric_Power_Sensor")
}

PREFIX ref: <http://example.org/reference#> 
SELECT ?tsid WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Chiller02_Electric_Power_Sensor> ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid
}

PREFIX ref: <http://example.org/reference#> 
SELECT ?tsid WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#CondPump01_Electric_Power_Sensor> ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid
}

PREFIX ref: <http://example.org/reference#> 
